+import { paginate, defaultPageSize } from './src/index.mjs';
+
+let failures = 0;
+const is = (a, b) => JSON.stringify(a) === JSON.stringify(b);
+const ok = (name, actual, expected) => {
+  const pass = Object.is(actual, expected) || is(actual, expected);
+  if (!pass) failures++;
+  console.log(`${pass ? 'ok  ' : 'FAIL'} ${name} -> ${JSON.stringify(actual)} (expected ${JSON.stringify(expected)})`);
+};
+
+ok('exports paginate', typeof paginate, 'function');
+ok('exports defaultPageSize', defaultPageSize, 20);
+
+const five = [1, 2, 3, 4, 5];
+ok('total', paginate(five, 1, 2).total, 5);
+ok('pageCount exact multiple', paginate(five, 1, 2).pageCount, 3);
+ok('pageCount partial last page', paginate(five, 1, 3).pageCount, 2);
+ok('page 1 items', paginate(five, 1, 2).items, [1, 2]);
+ok('page 2 items', paginate(five, 2, 2).items, [3, 4]);
+ok('page 3 partial items', paginate(five, 3, 2).items, [5]);
+ok('page 0 rejected', (() => { try { paginate(five, 0, 2); return 'no-throw'; } catch (e) { return e.constructor.name; } })(), 'RangeError');
+ok('empty total', paginate([], 1, 10).total, 0);
+ok('empty pageCount', paginate([], 1, 10).pageCount, 0);
+ok('empty items', paginate([], 1, 10).items, []);
+ok('past end items', paginate([1, 2, 3], 9, 2).items, []);
+ok('past end total preserved', paginate([1, 2, 3], 9, 2).total, 3);
+ok('pageSize > total', paginate([1, 2], 1, 100).pageCount, 1);
+
+const src = [1, 2, 3];
+const out = paginate(src, 1, 2);
+ok('result is not the input array', out.items !== src, true);
+out.items.push(99);
+out.items[0] = -1;
+ok('input array not mutated', src, [1, 2, 3]);
+
+for (const bad of [0, -1, -5, 1.5, NaN, Infinity, '2', null, undefined]) {
+  const asPage = (() => { try { paginate(five, bad, 2); return 'no-throw'; } catch (e) { return e.constructor.name; } })();
+  const asSize = (() => { try { paginate(five, 1, bad); return 'no-throw'; } catch (e) { return e.constructor.name; } })();
+  const pass = asPage === 'RangeError' && asSize === 'RangeError';
+  if (!pass) failures++;
+  console.log(`${pass ? 'ok  ' : 'FAIL'} rejects ${String(bad)} as page/size -> ${asPage}/${asSize}`);
+}
+
+let valid = 'no-throw';
+try { paginate(five, 1, 2); } catch (e) { valid = e.constructor.name; }
+ok('valid call does not throw', valid, 'no-throw');
+
+console.log(failures === 0 ? 'ALL CONTRACT CHECKS PASSED' : `${failures} CHECK(S) FAILED`);
+process.exitCode = failures === 0 ? 0 : 1;
