@@ -1 +1,46 @@
 export const defaultPageSize = 20;
+
+/**
+ * Check that a value is a positive integer (used for `page` and `pageSize`).
+ *
+ * `Number.isInteger` already rejects NaN, Infinity, strings and non-numbers;
+ * the `>= 1` check rejects zero and negative values. Together these cover
+ * 0, 1.5, NaN and friends with a single RangeError.
+ *
+ * @param {unknown} value
+ * @param {string} name
+ * @returns {number}
+ */
+function assertPositiveInteger(value, name) {
+  if (!Number.isInteger(value) || value < 1) {
+    throw new RangeError(`${name} must be a positive integer, received: ${String(value)}`);
+  }
+  return /** @type {number} */ (value);
+}
+
+/**
+ * Return a one-based page of `items`.
+ *
+ * The input array is never mutated and the returned `items` array is a fresh
+ * copy, so callers may freely mutate the result.
+ *
+ * @template T
+ * @param {readonly T[]} items
+ * @param {number} page one-based page number
+ * @param {number} pageSize items per page
+ * @returns {{items: T[], total: number, pageCount: number}}
+ */
+export function paginate(items, page, pageSize) {
+  if (!Array.isArray(items)) {
+    throw new TypeError(`items must be an array, received: ${typeof items}`);
+  }
+
+  assertPositiveInteger(page, 'page');
+  assertPositiveInteger(pageSize, 'pageSize');
+
+  const total = items.length;
+  const pageCount = Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+
+  return { items: items.slice(start, start + pageSize), total, pageCount };
+}

